// A StatusOr<T> holds either a usable value of type T, or an error Status
// explaining why such a value is not present. It is a convenient way to
// return either a value or an error from a function.

#pragma once

#include <new>
#include <type_traits>
#include <utility>

#include "ray/common/status.h"
#include "ray/util/logging.h"

namespace ray {

template <typename T>
class StatusOr {
 public:
  using value_type = T;

  // Default constructor produces a StatusOr holding a default-constructed T,
  // when T is default constructible.
  StatusOr() : status_(), has_value_(true) { new (&value_) T(); }

  // Constructs a StatusOr holding the given error status. It is a checked
  // error to pass an OK status here.
  StatusOr(const Status &status)  // NOLINT(runtime/explicit)
      : status_(status), has_value_(false) {
    RAY_CHECK(!status_.ok())
        << "StatusOr cannot be constructed from an OK status without a value.";
  }
  StatusOr(Status &&status)  // NOLINT(runtime/explicit)
      : status_(std::move(status)), has_value_(false) {
    RAY_CHECK(!status_.ok())
        << "StatusOr cannot be constructed from an OK status without a value.";
  }

  // Constructs a StatusOr holding the given value.
  StatusOr(const T &value)  // NOLINT(runtime/explicit)
      : status_(), has_value_(true) {
    new (&value_) T(value);
  }
  StatusOr(T &&value)  // NOLINT(runtime/explicit)
      : status_(), has_value_(true) {
    new (&value_) T(std::move(value));
  }

  // Copy construction/assignment.
  StatusOr(const StatusOr &other) : status_(other.status_), has_value_(other.has_value_) {
    if (has_value_) {
      new (&value_) T(other.value_);
    }
  }

  StatusOr &operator=(const StatusOr &other) {
    if (this == &other) {
      return *this;
    }
    Clear();
    status_ = other.status_;
    has_value_ = other.has_value_;
    if (has_value_) {
      new (&value_) T(other.value_);
    }
    return *this;
  }

  // Move construction/assignment.
  StatusOr(StatusOr &&other) noexcept
      : status_(std::move(other.status_)), has_value_(other.has_value_) {
    if (has_value_) {
      new (&value_) T(std::move(other.value_));
    }
  }

  StatusOr &operator=(StatusOr &&other) noexcept {
    if (this == &other) {
      return *this;
    }
    Clear();
    status_ = std::move(other.status_);
    has_value_ = other.has_value_;
    if (has_value_) {
      new (&value_) T(std::move(other.value_));
    }
    return *this;
  }

  // Allows implicit conversion from StatusOr<U> to StatusOr<T> whenever U is
  // convertible to T (e.g. StatusOr<Derived*> to StatusOr<Base*>).
  template <typename U,
            typename std::enable_if<std::is_convertible<U, T>::value &&
                                        !std::is_same<U, T>::value,
                                    int>::type = 0>
  StatusOr(const StatusOr<U> &other)  // NOLINT(runtime/explicit)
      : status_(other.status()), has_value_(other.ok()) {
    if (has_value_) {
      new (&value_) T(*other);
    }
  }

  template <typename U,
            typename std::enable_if<std::is_convertible<U, T>::value &&
                                        !std::is_same<U, T>::value,
                                    int>::type = 0>
  StatusOr(StatusOr<U> &&other)  // NOLINT(runtime/explicit)
      : status_(other.status()), has_value_(other.ok()) {
    if (has_value_) {
      new (&value_) T(std::move(*other));
    }
  }

  ~StatusOr() { Clear(); }

  // Returns true iff this StatusOr holds a value.
  bool ok() const { return has_value_; }
  explicit operator bool() const { return has_value_; }

  // Returns the contained status. When a value is held, this is an OK status.
  Status status() const { return ok() ? Status::OK() : status_; }

  // Returns the status code.
  StatusCode code() const { return ok() ? StatusCode::OK : status_.code(); }

  // Returns a reference to the contained value. It is a fatal error to call
  // this when the StatusOr does not hold a value.
  const T &value() const & {
    EnsureOk();
    return value_;
  }
  T &value() & {
    EnsureOk();
    return value_;
  }
  const T &&value() const && {
    EnsureOk();
    return std::move(value_);
  }
  T &&value() && {
    EnsureOk();
    return std::move(value_);
  }

  // Dereference operators. It is a fatal error to use them when the StatusOr
  // does not hold a value.
  const T &operator*() const & {
    EnsureOk();
    return value_;
  }
  T &operator*() & {
    EnsureOk();
    return value_;
  }
  const T &&operator*() const && {
    EnsureOk();
    return std::move(value_);
  }
  T &&operator*() && {
    EnsureOk();
    return std::move(value_);
  }

  const T *operator->() const {
    EnsureOk();
    return &value_;
  }
  T *operator->() {
    EnsureOk();
    return &value_;
  }

  // Returns the contained value if present, otherwise the provided default.
  template <typename U>
  T value_or(U &&default_val) const & {
    if (ok()) {
      return value_;
    }
    return static_cast<T>(std::forward<U>(default_val));
  }
  template <typename U>
  T value_or(U &&default_val) && {
    if (ok()) {
      return std::move(value_);
    }
    return static_cast<T>(std::forward<U>(default_val));
  }

  // Returns the contained value if present, otherwise a default-constructed T.
  T value_or_default() const & { return ok() ? value_ : T{}; }
  T value_or_default() && { return ok() ? std::move(value_) : T{}; }

  // If a value is held, applies f to it and returns the result; otherwise
  // returns the contained error status (wrapped in the result type of f).
  template <typename F>
  auto and_then(F &&f) const & -> decltype(std::forward<F>(f)(std::declval<const T &>())) {
    using Ret = decltype(std::forward<F>(f)(std::declval<const T &>()));
    if (ok()) {
      return std::forward<F>(f)(value_);
    }
    return Ret(status_);
  }
  template <typename F>
  auto and_then(F &&f) && -> decltype(std::forward<F>(f)(std::declval<T &&>())) {
    using Ret = decltype(std::forward<F>(f)(std::declval<T &&>()));
    if (ok()) {
      return std::forward<F>(f)(std::move(value_));
    }
    return Ret(std::move(status_));
  }

  // If an error is held, applies f to the status and returns its result;
  // otherwise returns the contained value (wrapped in the result type of f).
  template <typename F>
  auto or_else(F &&f) const & -> decltype(std::forward<F>(f)(std::declval<const Status &>())) {
    using Ret = decltype(std::forward<F>(f)(std::declval<const Status &>()));
    if (ok()) {
      return Ret(value_);
    }
    return std::forward<F>(f)(status_);
  }
  template <typename F>
  auto or_else(F &&f) && -> decltype(std::forward<F>(f)(std::declval<Status &&>())) {
    using Ret = decltype(std::forward<F>(f)(std::declval<Status &&>()));
    if (ok()) {
      return Ret(std::move(value_));
    }
    return std::forward<F>(f)(std::move(status_));
  }

